def pre(times):
    n = len(times)
    if n > 7:
        return False

    for i in range(n):
        t = times[i]
        if t < 0:
            return False
        if t > 12:
            return False

    if n > 1:
        for i in range(n - 1):
            if times[i] > times[i + 1]:
                return False

    return True


def expected_admitted(times):
    admitted = []
    for t in times:
        recent = 0
        for s in admitted:
            if t - 5 < s:
                if s <= t:
                    recent = recent + 1
        if recent < 3:
            admitted.append(t)
    return len(admitted)


def post(times, result):
    return result == expected_admitted(times)
